# Parse the graph from the context
edges_text = context.split("The graph has the following edges:")[1].split("Operation:")[0].strip()

# Build adjacency list
graph = {}
for line in edges_text.strip().split('\n'):
    if ' -> ' in line:
        source, target = line.split(' -> ')
        source = source.strip()
        target = target.strip()
        if source not in graph:
            graph[source] = []
        graph[source].append(target)

print("Adjacency list:")
for node in sorted(graph.keys()):
    print(f"  {node} -> {graph[node]}")

# BFS from c4ca4238a0 to find nodes at exactly depth 3
from collections import deque

start = "c4ca4238a0"
queue = deque([(start, 0)])
visited = {start: 0}
nodes_at_depth = {0: {start}, 1: set(), 2: set(), 3: set()}

while queue:
    node, depth = queue.popleft()
    if depth >= 3:
        continue
    if node in graph:
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited[neighbor] = depth + 1
                nodes_at_depth[depth + 1].add(neighbor)
                queue.append((neighbor, depth + 1))

print(f"\nNodes at depth 0: {nodes_at_depth[0]}")
print(f"Nodes at depth 1: {nodes_at_depth[1]}")
print(f"Nodes at depth 2: {nodes_at_depth[2]}")
print(f"Nodes at depth 3: {nodes_at_depth[3]}")

result = sorted(nodes_at_depth[3])
print(f"\nFinal result: {result}")
```

